import{_ as t,o as s,c as i,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Mathématiques, textes, listes et boucles","description":"","frontmatter":{"title":"Mathématiques, textes, listes et boucles"},"headers":[],"relativePath":"fr/projects/blocks-for-ha/collections.md","filePath":"fr/projects/blocks-for-ha/collections.md","lastUpdated":1793006827000}'),r={name:"fr/projects/blocks-for-ha/collections.md"};function o(n,e,l,u,c,d){return s(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="mathematiques-textes-listes-et-boucles" tabindex="-1">Mathématiques, textes, listes et boucles <a class="header-anchor" href="#mathematiques-textes-listes-et-boucles" aria-label="Permalink to &quot;Mathématiques, textes, listes et boucles&quot;">​</a></h1><p>Les fonctions correspondent aux capacités utiles de Blockly et ioBroker, adaptées à <strong>HA/Jinja</strong>. Les données ne sont pas exécutées comme code JavaScript. <a href="./blocks">Catalogue illustré de chaque type</a>.</p><h2 id="mathematiques" tabindex="-1">Mathématiques <a class="header-anchor" href="#mathematiques" aria-label="Permalink to &quot;Mathématiques&quot;">​</a></h2><p>Addition, soustraction, multiplication, division, puissance, racine carrée, valeur absolue, négation, logarithmes et exponentielles sont disponibles. Pas de conversion automatique des textes ou booléens. Les erreurs mathématiques restent des erreurs de modèle.</p><p>Les fonctions trigonométriques utilisent des <strong>degrés</strong> ; leurs inverses et <code>atan2</code> retournent des degrés. Constantes : π, e, nombre d’or, √2 et √½. Les propriétés testent pair, impair, entier, positif, négatif ou divisible par un diviseur non nul.</p><p>L’arrondi propose ordinaire, supérieur et inférieur à <strong>0–10 décimales</strong>. L’arrondi Jinja ordinaire suit la règle d’égalité vers le pair. Le modulo des nombres négatifs suit le signe du diviseur, pouvant différer de JavaScript. La limitation trie d’abord les bornes inversées.</p><p>Une liste numérique peut fournir somme, minimum, maximum, moyenne ou médiane ; l’élément aléatoire accepte tout type. Somme vide : 0 ; autres résultats vides : null. Entier aléatoire : bornes inclusives et au plus 10000 possibilités. Fraction aléatoire : 0 inclus à 1 exclu, pas de 0,00001, nouvelle valeur à chaque évaluation. Aucun usage cryptographique.</p><h2 id="textes" tabindex="-1">Textes <a class="header-anchor" href="#textes" aria-label="Permalink to &quot;Textes&quot;">​</a></h2><p>Texte simple ou multiligne, saut LF/CRLF/CR, assemblage extensible, ajout à une variable initialisée, longueur, vide, recherche, caractère, sous-texte, casse, suppression des espaces, comptage, remplacement et inversion.</p><ul><li>Positions à partir de <strong>1</strong> ; recherche absente : <strong>0</strong>.</li><li>Longueur et découpage suivent les <strong>points de code Unicode</strong>, pas les unités UTF-16 ou graphèmes composés.</li><li>Recherche, comptage et remplacement sont littéraux et sensibles à la casse, sans regex. Comptage sans chevauchement.</li><li>Recherche vide : comptage 0, remplacement inchangé.</li><li>Sous-texte : bornes inclusives. Bornes invalides/inversées : texte vide.</li><li>Suppression d’espaces : début, fin ou deux côtés, tabulations et sauts de ligne inclus.</li></ul><h2 id="listes" tabindex="-1">Listes <a class="header-anchor" href="#listes" aria-label="Permalink to &quot;Listes&quot;">​</a></h2><p>Liste vide/extensible, répétition d’un élément, longueur, vide, recherche de première/dernière occurrence, accès depuis le début/la fin ou aléatoire, remplacement/insertion/suppression, sous-liste, découpage/assemblage de texte, tri et inversion.</p><p>Toutes les positions commencent à <strong>1</strong>. Accès hors limites ou liste vide : null. Une modification affecte une nouvelle liste à la variable ; l’original n’est pas muté. Indice invalide : liste inchangée. Insertion autorisée jusqu’à longueur+1. Sous-liste inclusive ; bornes invalides/inversées : liste vide.</p><p>Séparateur vide lors du découpage : caractères Unicode. Tri numérique : nombres requis. Tri textuel : conversion en texte, avec ou sans distinction de casse. L’égalité est celle de HA/Python, pas l’identité de référence JavaScript.</p><h2 id="boucles-avec-variables" tabindex="-1">Boucles avec variables <a class="header-anchor" href="#boucles-avec-variables" aria-label="Permalink to &quot;Boucles avec variables&quot;">​</a></h2><p>Le compteur utilise des bornes entières fixes, fin incluse lorsqu’elle est atteinte par le pas. Le sens est automatique ; pas absolu &gt;0, au plus <strong>10000 tours</strong>. Il génère <code>repeat.for_each</code> et affecte la variable avant chaque corps.</p><p>Pour chaque valeur d’une liste, une variable nommée reçoit <code>repeat.item</code> avant le corps. Éviter la réutilisation de cette variable dans une boucle imbriquée. Les blocs de rupture et continuation ciblées de Blockly nécessitent une autre représentation que <code>stop</code> HA ; ils ne sont pas proposés comme équivalents directs.</p><p><a href="https://github.com/RaspberryPiFoundation/blockly/tree/develop/blocks" target="_blank" rel="noreferrer">Sources Blockly</a> · <a href="https://github.com/ioBroker/ioBroker.javascript" target="_blank" rel="noreferrer">Référence ioBroker</a> · <a href="https://www.home-assistant.io/docs/configuration/templating/" target="_blank" rel="noreferrer">Modèles HA</a>.</p>',18)])])}const h=t(r,[["render",o]]);export{m as __pageData,h as default};
